example_snippets:
Python: try:
    resp = client.completions.create(... )
    except RedwoodError as e:
      if e.is_retryable():
        sleep(e.get_retry_after() or default)
        retry()
      else:
        raise

TypeScript: try {
      await client.completions.create(...)
    } catch (e) {
      if (e.isRetryable()) {
        await backoff(e.retryAfterMs() || 200)
      } else {
        throw e
      }
    }

Go: resp, err := client.CreateCompletion(ctx, req)
    if err != nil {
      if RedwoodIsRetryable(err) {
        time.Sleep(RedwoodRetryAfter(err, default))
      }
    }
